const state = $getWorkflowStaticData('global');
const config = $input.first().json;
if (!state.checkpoint) {
  if (config.initial_checkpoint && !Number.isFinite(Date.parse(config.initial_checkpoint))) throw new Error('initial_checkpoint must be an ISO timestamp');
  state.checkpoint = config.initial_checkpoint ? new Date(config.initial_checkpoint).toISOString() : new Date().toISOString();
}
state.seen = state.seen || [];
return [{json:{...config, checkpoint:state.checkpoint, url:'https://api.github.com/repos/'+encodeURIComponent(config.owner)+'/'+encodeURIComponent(config.repo)+'/stargazers?per_page=100', attempt:0,pages:[],visited:[]}}];

const state = $getWorkflowStaticData('global');
const config = $('Load checkpoint').first().json;
const events = [];
for (const item of $input.all()) {
  const response = item.json;
  if (response.error || response.statusCode >= 400) throw new Error('GitHub star request failed; checkpoint unchanged.');
  if (!Array.isArray(response.body)) throw new Error('Unexpected GitHub stargazers response; checkpoint unchanged.');
  events.push(...response.body);
}
const seen = new Set(state.seen || []);
const fresh = events.filter(event => {
  if (!event?.starred_at || !event?.user?.login || !Number.isFinite(Date.parse(event.starred_at))) return false;
  const id = event.user.login + ':' + event.starred_at;
  if (Date.parse(event.starred_at) <= Date.parse(state.checkpoint) || seen.has(id)) return false;
  seen.add(id); return true;
}).sort((a, b) => Date.parse(a.starred_at) - Date.parse(b.starred_at))
.map(event => ({ login:event.user.login,starred_at:event.starred_at,owner:config.owner,repo:config.repo }));
if(!fresh.length) return [];
return [{json:{simulated:config.simulated===true,events:fresh, profiles:[],index:0, attempt:0,url:'https://api.github.com/users/'+encodeURIComponent(fresh[0].login)}}];

function commitEvents(state, events) {
