const clean=value=>String(value||'').replace(/[<>]/g,'').slice(0,500);
const leads=batch.profiles.filter(e=>e.profile.followers>100||e.profile.public_repos>50).map(source=>{const p=source.profile;return {json:{...source,profile:undefined,name:clean(p.name)||p.login,company:clean(p.company)||'Not listed',bio:clean(p.bio)||'Not listed',followers:p.followers,public_repos:p.public_repos,profile_url:'https://github.com/'+encodeURIComponent(p.login),processed_events:batch.events,notification_count:batch.profiles.filter(e=>e.profile.followers>100||e.profile.public_repos>50).length, simulated:batch.simulated===true},pairedItem:{item:0}};});
