return $input.all().map((item, index) => {
  const lead = $('Normalize and qualify enriched profile').itemMatching(index).json;
  const candidate = String(item.json.text || '').trim();
  const pitch = candidate && candidate.split(/[.!?]/).filter(Boolean).length === 1 ? candidate : 'Verified GitHub profile data suggests a relevant open-source conversation with ' + lead.company + '.';
  const escapeSlack = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/@(channel|here|everyone)/gi, '[mention removed]');
